// Reads the master SVGs in svg/*.svg and writes src/glyphs.ts: one entry per icon with its path data, whether it is
// stroked or filled, and its keyline. Runs before `tsc` in `pnpm build`; the output is committed so the package
// type-checks on a fresh clone too.
import { readdir, readFile, writeFile } from 'node:fs/promises';

const dir = new URL('../svg/', import.meta.url);
const files = (await readdir(dir)).filter((f) => f.endsWith('.svg')).sort();
const lines = [
  '// Generated by scripts/build-glyphs.mjs from svg/*.svg. Do not edit by hand: change the SVG and rebuild.',
  '',
  'export interface Glyph {',
  '  /** SVG path data on the 24 grid. */',
  '  d: string;',
  '  /** Stroked (2 px round) or filled. */',
  '  stroke: boolean;',
  '  /** The keyline shape the icon is drawn to: circle, square, portrait or landscape. */',
  '  keyline: string;',
  '}',
  '',
  'export const glyphs = {',
];
for (const file of files) {
  const svg = await readFile(new URL(file, dir), 'utf8');
  const d = /<path[^>]*\sd="([^"]+)"/.exec(svg)?.[1];
  if (!d) throw new Error(`${file}: no <path d="...">`);
  const head = svg.split('<path')[0];
  const stroke = !/fill="currentColor"/.test(head);
  const keyline = /data-keyline="([^"]+)"/.exec(svg)?.[1] ?? 'square';
  lines.push(
    `  '${file.replace(/\.svg$/, '')}': { d: '${d}', stroke: ${stroke}, keyline: '${keyline}' },`,
  );
}
lines.push(
  '} as const satisfies Record<string, Glyph>;',
  '',
  'export type IconName = keyof typeof glyphs;',
  '',
);
await writeFile(new URL('../src/glyphs.ts', import.meta.url), lines.join('\n'));
console.log(`Wrote src/glyphs.ts (${files.length} icons)`);

// Screen icons (svg/screens/*.svg): one per screen, currentColor plus the accent token. Kept as inner markup.
const sdir = new URL('../svg/screens/', import.meta.url);
const sfiles = (await readdir(sdir)).filter((f) => f.endsWith('.svg')).sort();
const out = [
  '// Generated by scripts/build-glyphs.mjs from svg/screens/*.svg. Do not edit by hand: change the SVG and rebuild.',
  '',
  '/** Inner SVG markup (24 grid) of each screen icon. Colours are currentColor and the accent token. */',
  'export const screenGlyphs = {',
];
for (const file of sfiles) {
  const svg = await readFile(new URL(file, sdir), 'utf8');
  const open = /<svg[^>]*>/.exec(svg)?.[0] ?? '';
  const attrs = ['fill', 'stroke', 'stroke-width', 'stroke-linecap', 'stroke-linejoin']
    .map((a) => new RegExp(`\\s${a}="([^"]+)"`).exec(open))
    .filter(Boolean)
    .map((m) => m[0].trim());
  // the accent is a style (presentation attributes can't take var()), with the literal as a fallback
  const inner = svg.slice(svg.indexOf(open) + open.length, svg.lastIndexOf('</svg>')).trim();
  out.push(
    `  '${file.replace(/\.svg$/, '')}': ${JSON.stringify(`<g ${attrs.join(' ')}>${inner}</g>`)},`,
  );
}
out.push('} as const;', '', 'export type ScreenIconName = keyof typeof screenGlyphs;', '');
await writeFile(new URL('../src/screen-glyphs.ts', import.meta.url), out.join('\n'));
console.log(`Wrote src/screen-glyphs.ts (${sfiles.length} screen icons)`);
